// Minimal RAR 4 STORE fixture containing only caller-supplied generated bytes.
// This avoids a RAR creator dependency and never reads personal manga.
const { crc32 } = require('node:zlib');

function header(type, flags, body) {
  const result = Buffer.alloc(7 + body.length);
  result[2] = type;
  result.writeUInt16LE(flags, 3);
  result.writeUInt16LE(result.length, 5);
  body.copy(result, 7);
  result.writeUInt16LE(crc32(result.subarray(2)) & 0xffff, 0);
  return result;
}

exports.storedRar = function storedRar(entries) {
  const blocks = [Buffer.from('526172211a0700', 'hex'), header(0x73, 0, Buffer.alloc(6))];
  for (const { name, bytes } of entries) {
    const filename = Buffer.from(name, 'ascii');
    const body = Buffer.alloc(25 + filename.length);
    body.writeUInt32LE(bytes.length, 0);
    body.writeUInt32LE(bytes.length, 4);
    body[8] = 0; // MS-DOS host
    body.writeUInt32LE(crc32(bytes), 9);
    body[17] = 20;
    body[18] = 0x30; // STORE (no compression)
    body.writeUInt16LE(filename.length, 19);
    body.writeUInt32LE(0x20, 21);
    filename.copy(body, 25);
    blocks.push(header(0x74, 0x8000, body), bytes);
  }
  blocks.push(header(0x7b, 0, Buffer.alloc(0)));
  return Buffer.concat(blocks);
};
